/**
 * Dispute evidence submitter cron — runs hourly at :15.
 *
 * Background: When a Stripe dispute's `evidence_due_by` is within 25 hours and
 * the defense pack is in `ready` status, this cron submits the assembled evidence
 * to Stripe via `disputes.update({ ..., submit: true })`.
 *
 * The 25-hour window ensures we submit 24h before the deadline (accounting for
 * 1-hour cron granularity). Stripe's evidence window closes at `evidence_due_by`;
 * late submissions are silently rejected, so running a safe buffer is mandatory.
 *
 * Schedule: ':15 * * * *' — offset from the reconciliation cron (:05) to avoid
 * simultaneous Stripe API bursts on the same Railway cron service.
 *
 * Idempotent: submitting evidence when status='submitted' is a no-op on Stripe's
 * side (Stripe ignores duplicate submissions). The RPC update is idempotent on
 * (dispute_id, status) per S21 contract.
 *
 * Failure modes handled:
 *   - Stripe 400 "evidence already submitted" → log warn, skip, do NOT mark failed
 *   - Stripe 400 "evidence window closed" → log error, mark 'failed'
 *   - Stripe 5xx / network error → log error, mark 'failed', allow next run retry
 *   - Missing defense pack row → log error, mark 'failed'
 *   - RPC status update failure → log error (dispute stays 'ready', retry next run)
 *
 * §S13.3 pattern: `stripe_disputes` and `dispute_defense_packs` are not in the
 * generated Supabase types (tables added in S21 migration). Query via untyped cast
 * following the CC28 pattern established in deposit-saga-reaper.ts.
 */

import cron from 'node-cron'
import { getStripe } from './shared/stripe'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'
import { RPC } from '@/lib/payments/contracts'
import type { DisputeDefensePackRow, StripeDisputeRow } from '@/lib/payments/contracts'

// ─── Constants ────────────────────────────────────────────────────────────────

/** Submit evidence when deadline is within this many hours. */
const SUBMIT_WINDOW_HOURS = 25

/** Maximum disputes to process per cron run — avoids Railway function timeout. */
const BATCH_SIZE = 10

/** Stripe evidence field max length. */
const STRIPE_TEXT_MAX = 9000

// ─── Untyped query helper types ───────────────────────────────────────────────

/**
 * Narrow projection of stripe_disputes used in the query.
 * Full row type is StripeDisputeRow from contracts.ts.
 */
type DisputeQueryRow = Pick<
  StripeDisputeRow,
  | 'id'
  | 'studio_id'
  | 'dispute_id'
  | 'charge_id'
  | 'evidence_due_by'
  | 'defense_pack_status'
  | 'defense_pack_url'
>

/**
 * RPC update helper — avoids spreading unknown-typed supabase.rpc signature.
 */
type RpcFn = (
  fn: string,
  args: Record<string, unknown>,
) => Promise<{ data: unknown; error: { message: string } | null }>

// ─── Evidence submission ──────────────────────────────────────────────────────

/**
 * Fetch the dispute_defense_packs row for the given Stripe dispute ID.
 * The join is `dispute_id` = dp_xxx Stripe ID (matches StripeDisputeRow.dispute_id).
 */
async function fetchDefensePack(disputeId: string): Promise<DisputeDefensePackRow | null> {
  const { data, error } = await (
    supabase.from('dispute_defense_packs') as unknown as {
      select: (cols: string) => {
        eq: (col: string, val: string) => {
          maybeSingle: () => Promise<{ data: DisputeDefensePackRow | null; error: { message: string } | null }>
        }
      }
    }
  )
    .select(
      'id, dispute_id, signed_consent_url, photo_release_url, session_photos_urls, chat_history_url, deposit_policy_text, receipt_url, bundle_pdf_url, generated_at',
    )
    .eq('dispute_id', disputeId)
    .maybeSingle()

  if (error) {
    logger.error({ disputeId, err: error }, 'dispute-evidence-submitter: failed to fetch defense pack')
    return null
  }

  return data
}

/**
 * Build a human-readable receipt line from the dispute row.
 * Included in Stripe's `uncategorized_text` evidence field.
 */
function buildReceiptLine(dispute: DisputeQueryRow): string {
  return [
    `Dispute ID: ${dispute.dispute_id}`,
    `Charge ID: ${dispute.charge_id}`,
    `Studio ID: ${dispute.studio_id}`,
    `Evidence due: ${dispute.evidence_due_by}`,
  ]
    .join('\n')
    .substring(0, STRIPE_TEXT_MAX)
}

/**
 * Submit assembled defense pack evidence to Stripe for a single dispute.
 *
 * Stripe evidence field mapping (from InkOS defense pack schema):
 *   - customer_signature    → signed consent form URL
 *   - service_documentation → photo release URL
 *   - refund_policy         → deposit policy text (first 9,000 chars)
 *   - uncategorized_text    → receipt provenance + chat history URL reference
 *
 * Session photos: full file upload to stripe.files.create() is out of scope for S21
 * (requires streaming Storage URLs through the Stripe Files API). URLs are surfaced
 * in uncategorized_text so Stripe reviewers can see them in the dispute portal.
 */
async function submitDisputeEvidence(dispute: DisputeQueryRow): Promise<void> {
  const pack = await fetchDefensePack(dispute.dispute_id)

  if (!pack) {
    logger.error(
      { disputeId: dispute.dispute_id },
      'dispute-evidence-submitter: no defense pack row found — marking failed',
    )
    await markDisputePackStatus(dispute.dispute_id, 'failed', null, null)
    return
  }

  // Build uncategorized_text: receipt provenance + photo URLs + chat history reference
  const receiptLine = buildReceiptLine(dispute)
  const chatRef = pack.chat_history_url
    ? `Chat history URL: ${pack.chat_history_url}`
    : null
  const photoRefs =
    pack.session_photos_urls.length > 0
      ? `Session photo URLs:\n${pack.session_photos_urls.join('\n')}`
      : null
  const uncategorizedParts = [receiptLine, chatRef, photoRefs].filter(
    (p): p is string => p !== null && p.length > 0,
  )
  const uncategorizedText = uncategorizedParts.join('\n\n').substring(0, STRIPE_TEXT_MAX)

  const stripe = getStripe()

  try {
    await stripe.disputes.update(dispute.dispute_id, {
      evidence: {
        customer_signature: pack.signed_consent_url ?? undefined,
        service_documentation: pack.photo_release_url ?? undefined,
        refund_policy:
          pack.deposit_policy_text.length > 0
            ? pack.deposit_policy_text.substring(0, STRIPE_TEXT_MAX)
            : undefined,
        uncategorized_text: uncategorizedText.length > 0 ? uncategorizedText : undefined,
        // Bundle PDF — surfaced as uncategorized_file if we have a URL. Full
        // stripe.files.create() streaming is Epic S46 scope; URL included in text for now.
        ...(pack.bundle_pdf_url
          ? { uncategorized_text: `${uncategorizedText}\n\nBundle PDF: ${pack.bundle_pdf_url}`.substring(0, STRIPE_TEXT_MAX) }
          : {}),
      },
      submit: true,
    })

    logger.info(
      {
        disputeId: dispute.dispute_id,
        chargeId: dispute.charge_id,
        studioId: dispute.studio_id,
        evidenceDueBy: dispute.evidence_due_by,
      },
      'dispute-evidence-submitter: evidence submitted to Stripe',
    )

    await markDisputePackStatus(
      dispute.dispute_id,
      'submitted',
      dispute.defense_pack_url,
      new Date().toISOString(),
    )
  } catch (err: unknown) {
    // Stripe 4xx: evidence already submitted (idempotent — warn, not error) or window closed (error)
    if (isStripeError(err)) {
      const code = err.code ?? ''
      const message = err.message ?? ''

      if (code === 'evidence_already_submitted' || message.includes('already been submitted')) {
        logger.warn(
          { disputeId: dispute.dispute_id, stripeCode: code },
          'dispute-evidence-submitter: evidence already submitted — treating as success',
        )
        await markDisputePackStatus(
          dispute.dispute_id,
          'submitted',
          dispute.defense_pack_url,
          new Date().toISOString(),
        )
        return
      }

      if (code === 'evidence_window_closed' || message.includes('evidence window')) {
        logger.error(
          { disputeId: dispute.dispute_id, stripeCode: code },
          'dispute-evidence-submitter: evidence window closed — marking failed',
        )
        await markDisputePackStatus(dispute.dispute_id, 'failed', null, null)
        return
      }
    }

    // Stripe 5xx / network / unexpected error — mark failed, allow retry next run
    logger.error(
      { disputeId: dispute.dispute_id, err },
      'dispute-evidence-submitter: Stripe call failed — marking failed',
    )
    await markDisputePackStatus(dispute.dispute_id, 'failed', null, null)
  }
}

// ─── Status update helper ─────────────────────────────────────────────────────

type DefensePackStatusValue = 'pending' | 'assembling' | 'ready' | 'submitted' | 'failed'

async function markDisputePackStatus(
  disputeId: string,
  status: DefensePackStatusValue,
  bundleUrl: string | null,
  submittedAt: string | null,
): Promise<void> {
  const rpc = supabase.rpc as unknown as RpcFn
  const { error } = await rpc(RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS, {
    p_dispute_id: disputeId,
    p_status: status,
    p_bundle_url: bundleUrl,
    p_submitted_at: submittedAt,
  })

  if (error) {
    logger.error(
      { disputeId, status, err: error },
      'dispute-evidence-submitter: RPC status update failed',
    )
  }
}

// ─── Stripe error type guard ──────────────────────────────────────────────────

interface StripeErrorLike {
  type: string
  code?: string
  message?: string
  statusCode?: number
}

function isStripeError(err: unknown): err is StripeErrorLike {
  return (
    typeof err === 'object' &&
    err !== null &&
    'type' in err &&
    typeof (err as Record<string, unknown>).type === 'string'
  )
}

// ─── Main exported function ───────────────────────────────────────────────────

/**
 * Find all disputes with a `ready` defense pack whose `evidence_due_by` is
 * within SUBMIT_WINDOW_HOURS (25h) and submit their evidence to Stripe.
 *
 * Exported for testing and direct invocation.
 */
export async function submitReadyDisputePacks(): Promise<void> {
  const cutoff = new Date(Date.now() + SUBMIT_WINDOW_HOURS * 60 * 60 * 1000).toISOString()

  const { data: disputes, error } = await (
    supabase.from('stripe_disputes') as unknown as {
      select: (cols: string) => {
        in: (col: string, vals: string[]) => {
          in: (col: string, vals: string[]) => {
            lt: (col: string, val: string) => {
              limit: (n: number) => Promise<{ data: DisputeQueryRow[] | null; error: { message: string } | null }>
            }
          }
        }
      }
    }
  )
    .select('id, studio_id, dispute_id, charge_id, evidence_due_by, defense_pack_status, defense_pack_url')
    .in('defense_pack_status', ['ready'])
    .in('status', ['needs_response', 'warning_needs_response'])
    .lt('evidence_due_by', cutoff)
    .limit(BATCH_SIZE)

  if (error) {
    logger.error({ err: error }, 'dispute-evidence-submitter: query failed')
    return
  }

  const rows = disputes ?? []

  if (rows.length === 0) {
    logger.info('dispute-evidence-submitter: no ready packs due within 25h')
    return
  }

  logger.info({ count: rows.length }, 'dispute-evidence-submitter: submitting evidence')

  for (const dispute of rows) {
    await submitDisputeEvidence(dispute).catch((err: unknown) => {
      logger.error(
        { disputeId: dispute.dispute_id, err },
        'dispute-evidence-submitter: unexpected error during submission',
      )
    })
  }
}

// ─── Cron schedule — every hour at :15 ───────────────────────────────────────

export function startDisputeEvidenceSubmitter(): void {
  cron.schedule('15 * * * *', () => {
    const startedAt = Date.now()

    submitReadyDisputePacks()
      .then(() => {
        logger.info(
          { duration_ms: Date.now() - startedAt, cron: 'dispute-evidence-submitter' },
          'dispute-evidence-submitter: cron run complete',
        )
      })
      .catch((err: unknown) => {
        logger.error(
          { err, duration_ms: Date.now() - startedAt, cron: 'dispute-evidence-submitter' },
          'dispute-evidence-submitter: cron run errored',
        )
      })
  })
}

