/**
 * Integration tests: dispute-evidence-submitter cron
 * (workers/cron/dispute-evidence-submitter.ts)
 *
 * Supabase + Stripe are fully mocked. All tests run unconditionally — no DB required.
 *
 * Architecture note: submitReadyDisputePacks() and submitDisputeEvidence() are the
 * two exported surfaces. Internal logic (fetchDefensePack, markDisputePackStatus) is
 * tested indirectly through the public exports.
 *
 * Coverage (6 tests):
 *  1. skips when no disputes found (submitReadyDisputePacks short-circuit)
 *  2. calls STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS with 'submitted' after Stripe succeeds
 *  3. marks 'failed' when fetchDefensePack returns null (no pack row)
 *  4. marks 'failed' when Stripe throws evidence_window_closed
 *  5. treats 'evidence already submitted' (400) as success → status='submitted'
 *  6. marks 'failed' on unexpected Stripe 5xx error
 */

import { vi, describe, it, expect, beforeEach } from 'vitest'
import { RPC } from '@/lib/payments/contracts'
import type { DisputeDefensePackRow } from '@/lib/payments/contracts'

// ---------------------------------------------------------------------------
// Mock logger — silence output in tests
// ---------------------------------------------------------------------------

vi.mock('../../../workers/lib/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}))

// ---------------------------------------------------------------------------
// Controllable Stripe mock
// ---------------------------------------------------------------------------

type StripeUpdateBehavior =
  | { outcome: 'success' }
  | { outcome: 'error'; code: string; message: string; statusCode?: number }

let stripeUpdateBehavior: StripeUpdateBehavior = { outcome: 'success' }
const stripeDisputesUpdateSpy = vi.fn()

vi.mock('../../../workers/cron/shared/stripe', () => ({
  getStripe: () => ({
    disputes: {
      update: stripeDisputesUpdateSpy,
    },
  }),
}))

// ---------------------------------------------------------------------------
// Controllable Supabase mock
// ---------------------------------------------------------------------------

/**
 * Narrow dispute row shape returned by the query mock.
 */
interface MockDisputeRow {
  id: string
  studio_id: string
  dispute_id: string
  charge_id: string
  evidence_due_by: string
  defense_pack_status: string
  defense_pack_url: string | null
}

/**
 * Per-test state controlling what the Supabase mock returns.
 */
interface MockState {
  disputeRows: MockDisputeRow[]
  packRow: DisputeDefensePackRow | null
  packFetchError: string | null
  rpcError: string | null
}

const mockState: MockState = {
  disputeRows: [],
  packRow: null,
  packFetchError: null,
  rpcError: null,
}

/** Track all RPC calls so tests can assert args. */
const rpcCallLog: Array<{ fn: string; args: Record<string, unknown> }> = []

vi.mock('../../../workers/lib/supabase', () => {
  const makeChainable = () => {
    // Dispute query chain:
    //   .from('stripe_disputes').select(...).in(...).in(...).lt(...).limit(...)
    const limitFn = vi.fn(async () => ({
      data: mockState.disputeRows,
      error: null,
    }))
    const lt2Fn = vi.fn(() => ({ limit: limitFn }))
    const in2Fn = vi.fn(() => ({ lt: lt2Fn }))
    const in1Fn = vi.fn(() => ({ in: in2Fn }))
    const selectDisputeFn = vi.fn(() => ({ in: in1Fn }))

    // Defense pack query chain:
    //   .from('dispute_defense_packs').select(...).eq(...).maybeSingle()
    const maybeSingleFn = vi.fn(async () => ({
      data: mockState.packRow,
      error: mockState.packFetchError ? { message: mockState.packFetchError } : null,
    }))
    const eqPackFn = vi.fn(() => ({ maybeSingle: maybeSingleFn }))
    const selectPackFn = vi.fn(() => ({ eq: eqPackFn }))

    const fromFn = vi.fn((table: string) => {
      if (table === 'stripe_disputes') return { select: selectDisputeFn }
      if (table === 'dispute_defense_packs') return { select: selectPackFn }
      throw new Error(`unexpected table in mock: ${table}`)
    })

    const rpcFn = vi.fn(async (fn: string, args: Record<string, unknown>) => {
      rpcCallLog.push({ fn, args })
      if (mockState.rpcError) {
        return { data: null, error: { message: mockState.rpcError } }
      }
      return { data: { id: 'mock-id', defense_pack_status: args['p_status'] }, error: null }
    })

    return { from: fromFn, rpc: rpcFn }
  }

  return { supabase: makeChainable() }
})

// ---------------------------------------------------------------------------
// Import the functions under test AFTER mocks are set up
// ---------------------------------------------------------------------------

import { submitReadyDisputePacks } from '../../../workers/cron/dispute-evidence-submitter'

// ---------------------------------------------------------------------------
// Helpers — build deterministic test data
// ---------------------------------------------------------------------------

function makeDisputeRow(overrides: Partial<MockDisputeRow> = {}): MockDisputeRow {
  return {
    id: 'row-uuid-001',
    studio_id: 'studio-001',
    dispute_id: 'dp_test_001',
    charge_id: 'ch_test_001',
    evidence_due_by: new Date(Date.now() + 20 * 60 * 60 * 1000).toISOString(), // 20h from now
    defense_pack_status: 'ready',
    defense_pack_url: 'https://storage.example.com/pack.pdf',
    ...overrides,
  }
}

function makePackRow(overrides: Partial<DisputeDefensePackRow> = {}): DisputeDefensePackRow {
  return {
    id: 'pack-uuid-001',
    dispute_id: 'dp_test_001',
    signed_consent_url: 'https://storage.example.com/consent.pdf',
    photo_release_url: 'https://storage.example.com/release.pdf',
    session_photos_urls: [
      'https://storage.example.com/photo1.jpg',
      'https://storage.example.com/photo2.jpg',
    ],
    chat_history_url: 'https://storage.example.com/chat.pdf',
    deposit_policy_text: 'Deposits are non-refundable within 48 hours of the appointment.',
    receipt_url: 'https://storage.example.com/receipt.pdf',
    bundle_pdf_url: 'https://storage.example.com/bundle.pdf',
    generated_at: new Date().toISOString(),
    ...overrides,
  }
}

function makeStripeError(code: string, message: string, statusCode = 400): Error & { type: string; code: string; statusCode: number } {
  const err = new Error(message) as Error & { type: string; code: string; statusCode: number }
  err.type = 'StripeInvalidRequestError'
  err.code = code
  err.statusCode = statusCode
  return err
}

