describe('submitReadyDisputePacks()', () => {
  it('skips when no disputes found — no Stripe calls made', async () => {
    mockState.disputeRows = []

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdateSpy).not.toHaveBeenCalled()
    expect(rpcCallLog).toHaveLength(0)
  })

  it('calls STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS with status=submitted after Stripe succeeds', async () => {
    mockState.disputeRows = [makeDisputeRow()]
    mockState.packRow = makePackRow()

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdateSpy).toHaveBeenCalledOnce()
    // Stripe disputes.update must include submit: true
    const [, evidenceArgs] = stripeDisputesUpdateSpy.mock.calls[0] as [string, { evidence: unknown; submit: boolean }]
    expect(evidenceArgs.submit).toBe(true)

    // RPC must have been called with status=submitted
    const submittedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'submitted',
    )
    expect(submittedCall).toBeDefined()
    expect(submittedCall?.args['p_dispute_id']).toBe('dp_test_001')
    expect(submittedCall?.args['p_submitted_at']).toBeTruthy()
  })

  it('marks status=failed when defense pack row is missing (fetchDefensePack returns null)', async () => {
    mockState.disputeRows = [makeDisputeRow()]
    mockState.packRow = null // no pack row in DB
    mockState.packFetchError = null

    await submitReadyDisputePacks()

    // Stripe must NOT be called when there's no pack
    expect(stripeDisputesUpdateSpy).not.toHaveBeenCalled()

    // RPC must have been called with status=failed
    const failedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'failed',
    )
    expect(failedCall).toBeDefined()
    expect(failedCall?.args['p_dispute_id']).toBe('dp_test_001')
  })

  it('marks status=failed when Stripe throws evidence_window_closed', async () => {
    mockState.disputeRows = [makeDisputeRow()]
    mockState.packRow = makePackRow()
    stripeUpdateBehavior = {
      outcome: 'error',
      code: 'evidence_window_closed',
      message: 'The evidence window for this dispute has closed.',
    }

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdateSpy).toHaveBeenCalledOnce()

    const failedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'failed',
    )
    expect(failedCall).toBeDefined()
  })

  it('treats already_submitted Stripe error as success → marks status=submitted', async () => {
    mockState.disputeRows = [makeDisputeRow()]
    mockState.packRow = makePackRow()
    stripeUpdateBehavior = {
      outcome: 'error',
      code: 'evidence_already_submitted',
      message: 'Evidence has already been submitted for this dispute.',
    }

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdateSpy).toHaveBeenCalledOnce()

    // Should mark submitted, not failed
    const submittedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'submitted',
    )
    expect(submittedCall).toBeDefined()

    const failedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'failed',
    )
    expect(failedCall).toBeUndefined()
  })

  it('marks status=failed on unexpected Stripe 5xx error', async () => {
    mockState.disputeRows = [makeDisputeRow()]
    mockState.packRow = makePackRow()
    stripeUpdateBehavior = {
      outcome: 'error',
      code: 'api_error',
      message: 'An error occurred with our connection to Stripe.',
      statusCode: 500,
    }

    await submitReadyDisputePacks()

    expect(stripeDisputesUpdateSpy).toHaveBeenCalledOnce()

    const failedCall = rpcCallLog.find(
      (c) => c.fn === RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS && c.args['p_status'] === 'failed',
    )
    expect(failedCall).toBeDefined()
  })
})

